// eSpeak-NG runs separately in a worker. No text or audio is sent to an inference service.
import initialize from './vendor/espeak/espeak-ng.js';
let enginePromise;
async function engine(){if(!enginePromise)enginePromise=initialize({locateFile:path=>new URL(`./vendor/espeak/${path}`,import.meta.url).href}).then(module=>({module,synth:new module.eSpeakNGWorker()})).catch(error=>{enginePromise=undefined;throw error});return enginePromise}
export function waveFromPcm(samples,sampleRate){const data=new ArrayBuffer(44+samples.length*2),view=new DataView(data);const tag=(offset,text)=>{for(let j=0;j<text.length;j++)view.setUint8(offset+j,text.charCodeAt(j))};tag(0,'RIFF');view.setUint32(4,36+samples.length*2,true);tag(8,'WAVE');tag(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,sampleRate,true);view.setUint32(28,sampleRate*2,true);view.setUint16(32,2,true);view.setUint16(34,16,true);tag(36,'data');view.setUint32(40,samples.length*2,true);for(let j=0;j<samples.length;j++)view.setInt16(44+j*2,samples[j],true);return data}
export async function synthesizeLocal({text,language='ur',rate=145}){const {synth}=await engine();if(typeof text!=='string'||!text.trim()||text.length>5000)throw Error('Speech text must contain 1–5000 characters.');if(synth.set_voice(language==='en'?'en':'ur')!==0)throw Error('Requested voice could not load.');synth.set_rate(Math.max(100,Math.min(210,Number(rate)||145)));const chunks=[];let size=0;synth.synthesize(text.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'),samples=>{if(samples?.length){const copy=new Int16Array(samples);chunks.push(copy);size+=copy.length}});if(!size)throw Error('No speech samples were generated.');const pcm=new Int16Array(size);let offset=0;for(const c of chunks){pcm.set(c,offset);offset+=c.length}return {buffer:waveFromPcm(pcm,synth.get_samplerate()),samples:size,sampleRate:synth.get_samplerate()}}
if(typeof self!=='undefined'&&typeof self.postMessage==='function'&&typeof document==='undefined')self.onmessage=async e=>{try{const result=await synthesizeLocal(e.data);self.postMessage({id:e.data.id,...result},[result.buffer])}catch(error){self.postMessage({id:e.data.id,error:error.message})}};
